eval(pm.environment.get('pmlib_code'));

// The token comes back as a Set-Cookie, not in the body: the body carries only
// {status, message} and answers 200 whether or not a token was minted, so a
// green response here proves nothing. The cookie is the only evidence.
var token = null;
pm.response.headers.each(function (h) {
    if (!token && h.key.toLowerCase() === 'set-cookie' && h.value.indexOf('Authorization=') === 0) {
        token = h.value.split(';')[0].substring('Authorization='.length);
    }
});

var body = null;
try { body = pm.response.json(); } catch (e) { body = null; }

pm.test('partner token issued', function () {
    pm.expect(JSON.stringify((body && body.errors) || []), 'authmanager rejected the credentials - partnerSecret is deployment-specific').to.equal('[]');
    pm.expect(token, 'no Authorization cookie in the response').to.be.a('string');
});

if (token) {
    // Cleared before validation, not after: client-mgmt rejects a stale, expired or
    // wrong-scope token exactly as it does a missing one - 'Full authentication is
    // required to access this resource' at HTTP 200 - so a token left behind after
    // failing its checks looks correctly populated while every registration fails.
    pm.environment.unset('authToken');

    var claims = {};
    try {
        var parsed = JSON.parse(pmlib.rs.b64utoutf8(token.split('.')[1]));
        if (parsed && typeof parsed === 'object') claims = parsed;
    } catch (e) {
        // Malformed token: both checks below fail on the empty claims and report it.
    }

    // scope is space-delimited, so membership rather than substring - a scope such as
    // add_oidc_client_readonly must not pass. A token minted for the wrong appId
    // authenticates perfectly and still cannot register a client; its scope is the
    // only thing that says so, and the failure it causes later does not mention it.
    var hasScope = typeof claims.scope === 'string' &&
        claims.scope.split(/\s+/).indexOf('add_oidc_client') !== -1;

    // These tokens are short-lived. Authenticating once and registering some minutes
    // later fails exactly like never authenticating at all.
    var notExpired = typeof claims.exp === 'number' && isFinite(claims.exp) &&
        claims.exp * 1000 > Date.now();

    pm.test('token carries add_oidc_client', function () {
        pm.expect(hasScope, 'wrong appId, or the token could not be decoded - it cannot register clients').to.equal(true);
    });

    pm.test('token is not already expired', function () {
        pm.expect(notExpired, 'authToken has no usable exp, or has already expired - re-run this request immediately before creating the client').to.equal(true);
    });

    // Stored only once both checks pass, so the environment never holds a token that
    // client-mgmt will refuse.
    if (hasScope && notExpired) pm.environment.set('authToken', token);
} else {
    pm.environment.unset('authToken');
}

