// eSignet 1.8 returns a CSRF token here that is NOT the XSRF-TOKEN cookie value,
// and the header has to carry this one. Reading the cookie instead - as the
// published mock-identity collection does - gets a bare 403 on every later step.
pm.environment.set('csrf_token', body.token);

pm.test('csrf token issued', function () {
    pm.expect(body.token).to.be.a('string');
});

